package com.shale.data.dao;
import static org.junit.jupiter.api.Assertions.*;import java.nio.file.*;import org.junit.jupiter.api.Test;
class ApplicationInstanceAdminReadDaoContractTest {
	@Test void queriesAreAdminCheckedTenantQualifiedSetBasedBoundedAndNumericallyGrouped()throws Exception{String s=Files.readString(Path.of("src","main","java","com","shale","data","dao","ApplicationInstanceAdminReadDao.java"));for(String token:new String[]{"verifyAdmin(c,tenant,actor)","COALESCE(is_admin,0)=1","SESSION_CONTEXT(N'ShaleClientId')","ai.ShaleClientId=?","JOIN dbo.Users u","ORDER BY ai.StartedAt DESC,ai.Id DESC","OFFSET ? ROWS FETCH NEXT ? ROWS ONLY","GROUP BY MajorVersion,MinorVersion,BuildVersion","COUNT_BIG(DISTINCT UserId)","ORDER BY MajorVersion DESC,MinorVersion DESC,BuildVersion DESC"})assertTrue(s.contains(token),token);assertEquals(1,count(s,"JOIN dbo.Users u"),"one set-based user join protects against N+1 lookup");assertFalse(s.contains("RowVer"));}
	@Test void phase6aAddsNoMigrationOrMutationContract()throws Exception{try(var files=Files.list(Path.of("..","docs","sql"))){assertTrue(files.noneMatch(p->p.getFileName().toString().contains("phase6a")));}String s=Files.readString(Path.of("src","main","java","com","shale","data","dao","ApplicationInstanceAdminReadDao.java"));for(String mutation:new String[]{"INSERT dbo.ApplicationInstances","UPDATE dbo.ApplicationInstances","DELETE FROM dbo.ApplicationInstances"})assertFalse(s.contains(mutation));}
	private static int count(String s,String token){int n=0,p=0;while((p=s.indexOf(token,p))>=0){n++;p+=token.length();}return n;}
}
